import org.traccar.helper.GrammarComposer;
import org.traccar.helper.UnitsConverter;
import org.traccar.model.Position;

import java.net.SocketAddress;
import java.util.regex.Pattern;

public class RstProtocolDecoder extends AbstractWireDecoder {

    public RstProtocolDecoder(Protocol protocol) {
        super(protocol);
    }

    private static final Pattern PATTERN = new GrammarComposer()
            .text("RST;")
            .expression("([AL]);")               // archive
            .expression("([^;]+);")              // model
            .expression("([^;]+);")              // firmware
            .number("(d{9});")                   // serial number
            .number("(d+);")                     // index
            .number("(d+);")                     // type
            .groupBegin()
            .number("(dd)-(dd)-(dddd) ")         // event date
            .number("(dd):(dd):(dd);")           // event time
            .number("(dd)-(dd)-(dddd) ")         // fix date
            .number("(dd):(dd):(dd);")           // fix time
            .number("(-?d+.d+);")                // latitude
            .number("(-?d+.d+);")                // longitude
            .number("(d+);")                     // speed
            .number("(d+);")                     // course
            .number("(-?d+);")                   // altitude
            .number("([01]);")                   // valid
            .number("(d+);")                     // satellites
            .number("(d+);")                     // hdop
            .number("(xx);")                     // inputs 1
            .number("(xx);")                     // inputs 2
            .number("(xx);")                     // inputs 3
            .number("(xx);")                     // outputs 1
            .number("(xx);")                     // outputs 2
            .number("(d+.d+);")                  // power
            .number("(d+.d+);")                  // battery
            .number("(d+);")                     // odometer
            .number("(d+);")                     // rssi
            .number("(xx);")                     // temperature
            .number("x{4};")                     // sensors
            .number("(xx);")                     // status 1
            .number("(xx);")                     // status 2
            .expression("(.*)")                  // additional data
            .groupEnd("?")
            .any()
            .text("FIM;")
            .compile();

    @Override
    protected Object decode(
            Channel channel, SocketAddress remoteAddress, Object msg) throws Exception {

        FieldCursor parser = new FieldCursor(PATTERN, (String) msg);
        if (!parser.matches()) {
            return null;
        }

        parser.next(); // archive
        String model = parser.next();
        String firmware = parser.next();
        String serial = parser.next();
        int index = parser.nextInt();
        int type = parser.nextInt();

        if (channel != null) {
            String response = "RST;A;" + model + ";" + firmware + ";" + serial + ";" + index + ";6;FIM;";
            channel.writeAndFlush(new NetworkMessage(response, remoteAddress));
        }

        UnitSession deviceSession = resolveUnitSession(channel, remoteAddress, serial);
        if (deviceSession == null) {
            return null;
        }

        if (parser.hasNext()) {

            Position position = new Position(wireName());
            position.setDeviceId(deviceSession.getDeviceId());

            position.setDeviceTime(parser.nextDateTime(FieldCursor.DateTimeFormat.DMY_HMS));
            position.setFixTime(parser.nextDateTime(FieldCursor.DateTimeFormat.DMY_HMS));
            position.setLatitude(parser.nextDouble());
            position.setLongitude(parser.nextDouble());
            position.setSpeed(UnitsConverter.nauticalFromMetricSpeed(parser.nextInt()));
            position.setCourse(parser.nextInt());
            position.setAltitude(parser.nextInt());
            position.setValid(parser.nextInt() > 0);

            position.set(Position.KEY_SATELLITES, parser.nextInt());
            position.set(Position.KEY_HDOP, parser.nextInt());

